 if(p.direct){const q2=Math.max(1,Math.min(5,+d.qty||1)),b2=f.querySelector('.shipsum'),t=(p.price||0)*q2;b2.innerHTML=`<div class="pr"><span>${T('Item','商品')} × ${q2}</span><b>$${t.toFixed(2)}</b></div><div class="pr"><span>${T('US shipping','美国运费')}</span><b>${T('Included','已含')}</b></div><div class="pr tot"><span>${T('Total due now','现在应付')}</span><b>$${t.toFixed(2)}</b></div>`;f.dataset.ship='0';return}
 const unit=(p.priceV&&p.priceV[v])||p.price||0,full=d.pay=='full',dep=DEP(p,v)*q,item=unit*q,box=f.querySelector('.shipsum');let ship=null,msg='';f.dataset.ship='';
