 const cur=Object.fromEntries(new FormData(f));if(cur.zip!=d.zip||cur.delivery!=d.delivery||cur.qty!=d.qty||cur.variant!=d.variant||cur.pay!=d.pay)return;
 if(ship!=null)f.dataset.ship=ship;const $$=n=>'$'+(+n).toFixed(2),sl=ship==null?(msg||T('enter your ZIP','请填写邮编')):(pick?T('$0.00 (local pickup in LA)','$0.00（洛杉矶自提）'):$$(ship));
